def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_defects = 0
    my_defects = 0
    for me, opp in history:
        if opp == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    last_me, last_opp = history[-1]

    # Chronic defector: defect if opponent defects too often.
    if opp_defects > n * 0.6:
        return 'D'

    # If opponent just defected:
    if last_opp == 'D':
        # Early retaliation, no forgiveness in first few rounds.
        if n < 10:
            return 'D'
        # Forgive rare defections if not in endgame.
        if n < 80 and opp_defects <= 2:
            if rng.random() < 0.5:
                return 'C'
        # If we also defected, try to break the mutual defection cycle.
        if last_me == 'D':
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        # Otherwise retaliate.
        return 'D'

    # Opponent just cooperated.
    if last_opp == 'C':
        # If we defected and opponent still cooperated, they are forgiving.
        # In the endgame, exploit very cooperative opponents.
        if last_me == 'D':
            if n >= 80 and (n - opp_defects) / n > 0.8:
                if rng.random() < 0.5:
                    return 'D'
            return 'C'
        # Both cooperated: continue cooperating.
        return 'C'

    return 'C'
